using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

// Provided infrastructure — do not modify. The engine's shared domain
// types (all milestones build on these).
public enum Priority { Low, Medium, High }
public enum Status { Todo, InProgress, Done }
public enum Role { Member, Admin }

public sealed record User(int Id, string Name, Role Role);
public sealed record Project(int Id, string Name, int OwnerId);
public sealed record TaskItem(
    int Id, int ProjectId, string Title,
    int? AssigneeId, Priority Priority, Status Status);

public static class DomainGuard
{
    public static void ValidTitle(string title)
    {
        if (title == null || title.Trim().Length == 0)
            throw new System.ArgumentException("title required");
        if (title.Trim().Length > 120)
            throw new System.ArgumentException("title too long");
    }

    public static void Defined(Priority p)
    {
        if (!System.Enum.IsDefined(typeof(Priority), p))
            throw new System.ArgumentException("bad priority");
    }

    public static void Defined(Status s)
    {
        if (!System.Enum.IsDefined(typeof(Status), s))
            throw new System.ArgumentException("bad status");
    }
}

